}
  
 .ytp-settings-button svg
  {
    -moz-transition: -moz-transform .4s cubic-bezier(.58,.24,.47,2.3);
    -webkit-transition: -webkit-transform .4s cubic-bezier(.58,.24,.47,1);
    -ms-transition: -ms-transform .4s cubic-bezier(.58,.24,.47,2.3);
    transition: transform .4s cubic-bezier(.58,.24,.47,2.3);
  }

  .ytp-settings-button[aria-expanded=true] svg
  {
    -moz-transform: rotateY(180deg) translateY(-5px);
    -ms-transform: rotateY(180deg) translateY(-5px);
    -webkit-transform: rotateY(180deg) translateY(-5px);
    transform: rotateY(180deg) translateY(-5px);
  }

  .ytp-big-mode .ytp-settings-button[aria-expanded=true] svg
  {
    -moz-transform: rotateY(180deg) translateY(-9px);
    -ms-transform: rotateY(180deg) translateY(-9px);
    -webkit-transform: rotateY(180deg) translateY(-9px);
    transform: rotateY(180deg) translateY(-9px);
  }

  :not([class*="video-extras-sparkbar"])
{
    color: #fca4cd!important;
}

  .load-more-button,#background,#frosted-glass,.ytd-playlist-panel-renderer,.button-container,#guide-content,#page-header,.ytd-tabbed-page-header,.ytdMiniplayerComponentHost
  {
    background: transparent!important;
  }

  .load-more-button
  {
    background: transparent!important;
  }

  [role="alert"],.content-region,.yt-uix-checkbox-on-off .checked:before
  {
    display: none!important;
  }

  :not(#​) :link
  {
    color: #ff0077!important;
  }

  :not(#​) :visited
  {
    color: #ff3dbb!important;
  }

  :not(#​) select
  {
    background: black!important;
  }

.html5-play-progress, .ytp-play-progress {
   background: url("https://i.imgur.com/cmEmClD.png") repeat-x !important; 
}

.html5-load-progress, .ytp-load-progress {
  width: 100%;
	height: 50vh; 
  background-image: url("https://static.vecteezy.com/system/resources/thumbnails/058/309/127/small/sky-blue-cloud-background-sky-anime-cartoon-seamless-pattern-summer-clear-sky-over-beach-wallpaper-panorama-repeat-landscape-nature-sunrise-sky-abstract-white-cloud-for-games-background-vector.jpg");
  background-repeat: repeat-x;
  background-size: cover;
}

.html5-scrubber-button, .ytp-scrubber-button {
   background: url("http://i.imgur.com/wEswxu3.png") !important;
  width: 23px !important;
  height: 23px !important;
  border: none !important;
  margin-left: -5px !important;
  margin-top: -3px !important;
}
.ytp-progress-bar-container:hover .ytp-scrubber-button,
.ytp-progress-bar-container:hover .ytp-load-progress{
	image-rendering: pixelated;
}
.html5-progress-bar-container, .ytp-progress-bar-container {
   height: 12px !important;
}
.html5-progress-bar, .ytp-progress-bar {
   margin-top: 12px !important;
}
.html5-progress-list, .ytp-progress-list, .video-ads .html5-progress-list.html5-ad-progress-list, .video-ads .ytp-progress-list.ytp-ad-progress-list {
   height: 12px !important;
}
